// Session handling using Web Crypto API for HMAC-SHA256 signing.
// The session cookie value is `base64(payload).base64(signature)`.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const SECRET_PATH = '/home/user/session_secret.txt';

let cachedSecret: string | null = null;

function getSecret(): string {
  if (cachedSecret !== null) return cachedSecret;
  const buf = readFileSync(SECRET_PATH);
  cachedSecret = buf.toString('utf8').trim();
  if (!cachedSecret) {
    throw new Error('Session secret is empty');
  }
  return cachedSecret;
}

const encoder = new TextEncoder();

function toBase64Url(bytes: Uint8Array): string {
  let binary = '';
  for (let i = 0; i < bytes.length; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  const b64 = btoa(binary);
  return b64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function fromBase64Url(s: string): Uint8Array {
  const padded = s + '='.repeat((4 - (s.length % 4)) % 4);
  const b64 = padded.replace(/-/g, '+').replace(/_/g, '/');
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

async function getHmacKey(secret: string): Promise<CryptoKey> {
  return crypto.subtle.importKey(
    'raw',
    encoder.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign', 'verify'],
  );
}

async function hmacSign(data: Uint8Array): Promise<Uint8Array> {
  const key = await getHmacKey(getSecret());
  const sig = await crypto.subtle.sign('HMAC', key, data);
  return new Uint8Array(sig);
}

// Constant-time comparison.
function timingSafeEqual(a: Uint8Array, b: Uint8Array): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    diff |= a[i] ^ b[i];
  }
  return diff === 0;
}

export async function createSessionToken(username: string): Promise<string> {
  const payload = encoder.encode(JSON.stringify({ u: username, t: Date.now() }));
  const payloadB64 = toBase64Url(payload);
  const sig = await hmacSign(encoder.encode(payloadB64));
  const sigB64 = toBase64Url(sig);
  return `${payloadB64}.${sigB64}`;
}

export async function verifySessionToken(
  token: string,
): Promise<string | null> {
  if (!token || typeof token !== 'string') return null;
  const dot = token.indexOf('.');
  if (dot < 0) return null;
  const payloadB64 = token.slice(0, dot);
  const sigB64 = token.slice(dot + 1);
  let payloadBytes: Uint8Array;
  let sigBytes: Uint8Array;
  try {
    payloadBytes = fromBase64Url(payloadB64);
    sigBytes = fromBase64Url(sigB64);
  } catch {
    return null;
  }
  const expected = await hmacSign(encoder.encode(payloadB64));
  if (!timingSafeEqual(expected, sigBytes)) return null;
  try {
    const json = new TextDecoder().decode(payloadBytes);
    const data = JSON.parse(json) as { u?: string };
    if (typeof data.u !== 'string' || !data.u) return null;
    return data.u;
  } catch {
    return null;
  }
}

export function readSessionCookie(request: Request): string | null {
  const cookieHeader = request.headers.get('Cookie');
  if (!cookieHeader) return null;
  for (const cookie of cookieHeader.split(';')) {
    const trimmed = cookie.trim();
    const eq = trimmed.indexOf('=');
    if (eq < 0) continue;
    const key = trimmed.slice(0, eq);
    const value = trimmed.slice(eq + 1);
    if (key === 'session') {
      try {
        return decodeURIComponent(value);
      } catch {
        return value;
      }
    }
  }
  return null;
}

export function buildSessionCookie(value: string): string {
  // HttpOnly + Path=/ as required; do not set Secure in dev over http.
  return `session=${encodeURIComponent(value)}; Path=/; HttpOnly; SameSite=Lax`;
}

export function buildClearSessionCookie(): string {
  return `session=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0`;
}
